import os
import json
from openai import OpenAI

def normalize_expense(payload, config=None):
    config = config or {}
    client = OpenAI(api_key=config.get("api_key") or os.environ.get("OPENAI_API_KEY"))
    result = client.responses.create(
        model=config.get("model", "gpt-4.1-mini"),
        input=[
            {
                "role": "system",
                "content": (
                    "Extract and normalize expense information into a JSON object with the "
                    "schema: {merchant_name, transaction_date, amount, currency, category, "
                    "payment_method, tax_amount, tip_amount, total_amount, line_items, "
                    "confidence}. Use null for unknown fields. Return only valid JSON."
                ),
            },
            {
                "role": "user",
                "content": json.dumps(payload),
            },
        ],
        text={"format": {"type": "json_object"}},
    )
    result = json.loads(result.output_text)
    return result
